\label{d.ndls}
Let $\varepsilon>0$, $m>0$, $E\subset\mathbb{R}^p$ a neighborhood of $0$ and let $U\subset\mathbb{R}^n$ be an open subset. Let $\sigma\in C^\infty(U\times\mathbb{R}^n\setminus\{0\})$ be homogeneous of degree $m$ in the second variable. For each $x\in U$ let $S^*_x =\{\xi\in\mathbb{R}^n\ |\ \sigma(x,\xi)=1\}$ and $d_x\mu$ be the area measure on $S^*_x$. Let $S^*U=\{(x,\xi)\in U\times \mathbb{R}^n\ |\ \xi\in S^*_x\}$.
\begin{enumerate}
\item    Given a compact subset $\Omega\subset U\times(\mathbb{R}^n\setminus\{0\})$ let $X=\{(x,\tau,\xi)\in \Omega\times\mathbb{R}^n\ |\ \xi\in S^*_x\}$. We call a \textbf{deformation of the height function for $\sigma$ over $\Omega$} any family $(f_\eta)_{\eta\in E}$ of continuous, real-valued functions on $X$, smooth in the third variable $\xi$, with the following properties:
\begin{itemize}
\item for each $(x,\tau,\xi)\in \Omega\times \mathbb{R}^n$ such that $\xi\in S^*_x$, $f_0(x,\tau,\xi)=\langle\tau,\xi\rangle$
\item for each $\alpha\in\mathbb{N}^n$, the map $\eta \mapsto \partial^\alpha_\xi f_\eta$ is continuous for the topology of uniform convergence on compact sets.
\end{itemize}
\item We say that $\sigma$ has \textbf{$\varepsilon$-non-degenerate level sets} if, for any compact subset $\Omega$ of $U\times (\mathbb{R}^n\setminus\{0\})$ and any deformation of the height function $(f_\eta)_\eta$ for $\sigma$ over $\Omega$ there exists $V\subset\mathbb{R}^p$ a neighborhood of $0$ depending only on $\Omega$ (and $\varepsilon$) such that for each $\gamma\in C^\infty(S^*U)$ and each continuous family of smooth functions on $(u_\eta)_{\eta}\in \left(C^\infty\left(\mathbb{R}^n\right)\right)^E$, there exists $C<+\infty$ such that for each each $\eta\in V$, each $(x,\tau)\in \Omega$ and each $\lambda>0$,
\begin{equation}\label{e.decay}
\Big|\int_{S^*_x}e^{i\lambda f_\eta(x,\tau,\xi)}u_\eta(\xi)\gamma(x,\xi)d_x\mu(\xi)\Big|\leq C\lambda^{-\varepsilon}\, .
\end{equation}
We say that $\sigma$ has \textbf{non-degenerate level sets} if it has $\varepsilon$-non-degenerate level sets for some $\varepsilon>0$.
\item Let $\varepsilon>0$. We say that a homogeneous symbol on a manifold has non-degenerate (resp. $\varepsilon$-non-degenerate) level sets if it has this property when written in any local coordinate system.
  \end{enumerate}

\label{l.toolbox}
  Let $U\subset\mathbb{R}^n$ and let $\psi\in C^\infty(U\times U\times\mathbb{R}^n)$ be a proper phase function. For each $t>0$, let $\psi_t=t^{-1}\psi(\cdot,\cdot,t\cdot)$. Then,
  \begin{enumerate}
  \item For each $x,y\in U$ and each $t>0$, $\psi_t(x,y,0)=0$.
  \item For each $x\in U$, each $t>0$ and each $\xi\in\mathbb{R}^n$, $\psi_t(x,x,\xi)=0$.
  \item For each $x\in U$, each $t>0$ and each $\xi\in\mathbb{R}^n$, $\partial_{x,y}\psi_t(x,x,\xi)=(\xi,-\xi)$.
  \item The sequence $(\psi_t)_{t>0}$ converges in $C^\infty(U\times U\times\mathbb{R}^n)$ as $t\rightarrow 0$ to the function $\psi_0$ defined by $\psi_0(x,y,\xi)=\partial_\xi\psi(x,y,0)\xi$. In other words, for each compact subset $\Omega\subset U$, each $R<+\infty$ and each $\alpha,\beta,\gamma\in\mathbb{R}^n$,
    \[\lim_{t\rightarrow 0}\sup_{x,y\in\Omega,\ |\xi|\leq R}\left|\partial^\alpha_\xi\partial^\beta_x\partial^\gamma_y\psi_t(x,y,\xi)-\partial^\alpha_\xi\partial^\beta_x\partial^\gamma_y\psi_0(x,y,\xi)\right|=0.\]
   \item The sequence $(\psi_t)_{t\geq 0}$ is bounded in $C^\infty(U\times U\times\mathbb{R}^n)$.
  \end{enumerate}

\label{l.jatz}
The function $H_P$ satisfies the following properties.
\begin{enumerate}
\item The function $t\mapsto H_P(\cdot,\cdot,\cdot,t)$ extends continuously to $t=0$ as a function from $\mathbb{R}_+$ to $C^\infty(U\times U\times\mathbb{R}^n)$ and
\[H_P(x,y,\xi,0)=\sigma_P\left(x,y,\partial_{x,y}(\partial_\xi\psi(x,y,0)\xi)\right).\]
\item Uniformly for $t\geq 0$ and $x,y$ in compact subsets of $U$ and $\xi\in \mathbb{R}^n$,
\[
H_P(x,y,\xi,t)-H_P(x,y,\xi,0)=O\left(t|x-y||\xi|^{d+1}\right)\, .
\]
\end{enumerate}

