Applying \eqref{e.color.10} to compare the right hand sides of each line we get Equation \eqref{e.color.9}.

\label{p.fat}
For all $n\in\mathbb{N}$, $n\geq 2$ we define $k_0=k_0(n)\in\mathbb{N}$ as follows. We set $k_0(2)=5$, $k_0(3)=3$, $k_0(4)=3$ and $\forall n\geq 5,\, k_0(n)=2$. Fix $n\geq 2$ and $m>0$. Let $U\subset\mathbb{R}^n$ be an open subset. Then, the set of $\sigma\in S^m_{h,+}(U)$ such that for each $(x,\xi)\in U\times(\mathbb{R}^n\setminus\{0\})$ there exists $j\in\{2,\dots,k_0\}$ such that
\begin{equation}\label{e.fat}
\sigma^{j-1}(x,\xi)\partial_\xi^j\sigma(x,\xi)\neq \frac{m(m-1)\dots(m-j+1)}{m^j}\left(\partial_\xi\sigma(x,\xi)\right)^{\otimes j}
\end{equation}
 is open and dense in $S^m_{h,+}(U)$.

\begin{enumerate}
\item For each $j,p\in\mathbb{N}$, $p\geq 1$, let $\textup{Sym}_p^j$ be the space of symmetric $j$-linear forms over $\mathbb{R}^p$. This is a vector space of dimension $\binom{p+j-1}{j}$. We adopt the convention that $\textup{Sym}_p^0=\mathbb{R}$.
\item Let $X$ be a smooth manifold. For each $k\geq 0$ we denote by $\mathcal{J}^k(X)$ the $k$-th jet space of mappings from $X$ to 
$\mathbb{R}$, that is, the space $J^k(X,\mathbb{R})$ introduced in Definition 2.1 of Chapter II of \cite{gg_stable}. For any $p\in\mathbb{N}$ and any open subset $V\subset\mathbb{R}^p$, the space $\mathcal{J}^k(V)$ is canonically isomorphic to $V\times\bigoplus_{j=0}^k\textup{Sym}_p^j$. We will denote its elements by $(\xi,\omega)$ where $\xi\in V$ and $\omega=(\omega_0,\dots,\omega_k)\in\bigoplus_{j=0}^k\textup{Sym}_p^j$.
\item Let $X$ be a smooth manifold and $k\in\mathbb{N}$. For each $f\in C^\infty(X)$, we write $j^kf$ for the section of $\mathcal{J}^k(X)$ whose value at each point is the $k$-jet of $f$ at this point (see the paragraph below Definition 2.1 of Chapter II of \cite{gg_stable}).
\end{enumerate}

\label{l.jets_of_homogeneous_functions}
Fix $k\in\mathbb{N}$. Let $H^k_m$ be the subset of $\iota^*\mathcal{J}^k\left(\mathbb{R}^n\setminus\{0\}\right)$ of jets of $m$-homogeneous functions. Then,
\begin{enumerate}
\item The set $H^k_m$ is characterized by the following equations:
\[
H^k_m=\cap_{j=0}^{k-1}\left\{(\xi,\omega)\in\iota^*\mathcal{J}^k\left(\mathbb{R}^n\setminus\{0\}\right)\, \Big |\, \omega_{j+1}(\xi,\dots)=(m-j)\omega_j\right\}\, .
\]
\item The set $H^k_m$ is a submanifold of $\iota^*\mathcal{J}^k\left(U\times\mathbb{R}^n\setminus\{0\}\right)$ of the same dimension as $\mathcal{J}^k\left(S^{n-1}\right)$.
\item The map $\rho|_{H^k_m}:H^k_m\rightarrow\mathcal{J}^k\left(U\times S^{n-1}\right)$ is a diffeomorphism.
\end{enumerate}

For each $j\in\{0,\dots,k-1\}$, each $l\in\{2,\dots,k\}$ and each $(\xi,\omega)\in\iota^*\mathcal{J}^k\left(\mathbb{R}^n\setminus\{0\}\right)$, let, as before, $F_m^j(\xi,\omega)=\omega_{j+1}(\xi,\dots)-(m-j)\omega_j\in Sym_n^{j-1}$. Moreover, let $\textup{Sym}_n^l|_{\xi^\perp}$ be the set of symmetric $l$-linear forms acting on the orthogonal of $\xi$ in $\mathbb{R}^n$ and let $G_m^l(\xi,\omega)=\omega_l|_{\xi^\perp}-\frac{m(m-1)\dots(m-l+1)}{m^l}\left(\omega_1|_{\xi^\perp}\right)^{\otimes l}\in \textup{Sym}_n^l|_{\xi^\perp}$. Then, $Y_m^k\cap H_m^k$ is the intersection of the zero sets of the functions $F_m^j$ and $G_m^l$ for $j\in\{0,\dots,k-1\}$ and $l\in\{2,\dots,k\}$. In particular, it is closed. Note first that $\partial_{\omega_0}F_m^0=m\neq 0\in\textup{Hom}\left(\textup{Sym}_n^0,\textup{Sym}_n^0\right)\simeq\mathbb{R}$. In particular this map is invertible. We will now prove that for each $l\in\{2,\dots,k\}$, the map $(\partial_{\omega_l} F_m^{l-1},\partial_{\omega_l} G_m^l)$ is of maximal rank on $Y^k_m$. For any $(\xi,\omega)\in Y^k_m$ and any $l\in\{2,\dots,k\}$, $(\partial_{\omega_l}F_m^{l-1}(\xi,\omega),\partial_{\omega_l}G_m^l(\xi,\omega))$ acts as follows.
\begin{align*}
\textup{Sym}_n^l&\rightarrow \textup{Sym}_n^{l-1}\bigoplus\textup{Sym}_n^l|_{\xi^\perp}\\
\eta_l&\mapsto(\eta_l(\xi,\dots),\omega_0^{l-1}\eta_l|_{\xi^\perp})\, .
\end{align*}
But this map is invertible. To see this, let $pr_{\xi^\perp}^*:\textup{Sym}_n^l|_{\xi^\perp}\rightarrow\textup{Sym}_n^l$ be the pull-back map by the orthogonal projection onto the orthogonal of $\xi$. Also, recall that on $Y^k_m$, we have $\omega_0>0$. Then, the inverse of $(\partial_{\omega_l}F_m^{l-1}(\xi,\omega),\partial_{\omega_l}G_m^l(\xi,\omega))$ is
\begin{align*}
 \textup{Sym}_n^{l-1}\bigoplus\textup{Sym}_n^l|_{\xi^\perp}&\rightarrow\textup{Sym}_n^l\\
(\eta_{l-1},\eta|_{\perp})&\mapsto |\xi|^{-2}\langle \xi,\cdot\rangle\otimes\eta_{l-1}+\omega_0^{1-l}pr_{\xi^\perp}^*\eta_\perp\, .
\end{align*}
All in all, we have shown so far that $\partial_{\omega_0} F_m^0$ is surjective and that for each $l\in\{2,\dots,k\}$, $(\partial_{\omega_l}F_m^{l-1},\partial_{\omega_l}G_m^l)$ is of maximal rank. Therefore, $Y_m^k\cap H^k_m$ is a submanifold of $H^k_m$ of codimension
\begin{align*}
codim_{H^k_m}(Y^k_m\cap H^k_m)&=codim_{\iota^*\mathcal{J}^k\left(\mathbb{R}^n\setminus\{0\}\right)}\left(Y^k_m\cap H^k_m\right)-codim_{\iota^*\mathcal{J}^k\left(\mathbb{R}^n\setminus\{0\}\right)}\left(H^k_m\right)\\
&=1+\sum_{l=2}^k\binom{n+l-1}{l}-\sum_{j=0}^{k-1}\binom{n+j-1}{j}\\
&=\binom{n+k-1}{k}-\binom{n+1-1}{1}\\
&=\sum_{j=2}^k\binom{n+j-2}{j}
\end{align*}
where in the last line we use the same binomial identity as in Equation \eqref{e.johf.2}.

\label{l.jets_back_home}
Let $k\in\mathbb{N}$. Let $\pi: U\times S^{n-1}\rightarrow S^{n-1}$ be the map $(x,\xi)\mapsto \xi$. Also, for each $x\in U$, let $\iota_x:S^{n-1}\rightarrow U\times S^{n-1}$ be the map $\xi\mapsto (x,\xi)$. Then, there exists a surjective vector bundle morphism $pr_2:\mathcal{J}^k\left(U\times S^{n-1}\right)\rightarrow\pi^*\mathcal{J}^k\left(S^{n-1}\right)$ such that for each $x\in U$, the following diagram commutes:
\[
\begin{tikzcd}
C^\infty\left(U\times S^{n-1}\right)\arrow{rr}{\iota_x^*} \arrow{d}{j^k} & & C^\infty\left(S^{n-1}\right) \arrow{d}{j^k}\\
\mathcal{J}^k\left(U\times S^{n-1}\right)\arrow{r}{pr_2} & \pi^*\mathcal{J}^k\left(S^{n-1}\right)\arrow{r}{\iota_x^*} & \mathcal{J}^k\left(S^{n-1}\right)\, .
\end{tikzcd}
\]
In particular, $pr_2$ is a submersion.

\label{l.jets_we_want}
Let $k\in\mathbb{N}$, $k\geq 2$. Let $\sigma\in S^m_{h,+}(U)$. Then, there exists $(x,\xi)\in U\times(\mathbb{R}^n\setminus\{0\})$ such that for each $j\in\{2,\dots,k\}$
\begin{equation}\label{e.jww.1}
\sigma^{j-1}(x,\xi)\partial_\xi^j\sigma(x,\xi)=\frac{m(m-1)\dots(m-j+1)}{m^j}\left(\partial_\xi\sigma(x,\xi)\right)^{\otimes j}
\end{equation}
if and only if $pr_2\circ j^k\left(\sigma|_{U\times S^{n-1}}\right)\left(U\times S^{n-1}\right)\cap \rho\left(Y^k_m\right)\neq\emptyset$.

Firstly, by Lemma \ref{l.jets_we_want}, Equation \eqref{e.fat} has solutions in $U\times(\mathbb{R}^n\setminus\{0\})$ if and only if $j^k\left(\sigma|_{U\times S^{n-1}}\right)(U\times S^{n-1})\cap pr_2^{-1}\left(\rho(Y^k_m)\right)\neq\emptyset$. Now, by Lemmas \ref{l.jets_of_homogeneous_functions} and \ref{l.jet_equations}, $\rho\left(Y^k_m\right)$ is a closed submanifold of $\mathcal{J}^k\left(S^{n-1}\right)$ of codimension $\sum_{j=2}^k\binom{n+j-2}{j}$. Since moreover, by Lemma \ref{l.jets_back_home}, $pr_2$ is a submersion, $Z^k_m=pr_2^{-1}\left(\rho(Y^k_m)\right)$ has the same codimension in $\mathcal{J}^k\left(U\times S^{n-1}\right)$. At this point, we apply Thom's transversality theorem (Corollary 4.10 of Chapter II of \cite{gg_stable}). This theorem states that the functions $f\in C^\infty\left(U\times S^{n-1}\right)$ such that $j^k(f)(U\times S^{n-1})$ is transverse to $Z^k_m$ is open and dense. But $j^k(f)\left(U\times S^{n-1}\right)$ has dimension at most $2n-1$ so if $k$ is such that
\begin{equation}\label{e.fat.1}
2n-1<\sum_{j=2}^k\binom{n+j-2}{j}
\end{equation}
then such a transverse intersection must be empty. Inequality \eqref{e.fat.1} is satisfied for instance for $n=2$ and $k=5$, for $n\in\{3,4\}$ and $k=3$ and for $n\geq 5$ and $k=2$. This ends the proof of the proposition.

\label{l.source}
Firstly, the spectral function $\tilde{E}_L(x,y)$ defines a tempered distribution of the $L$ variable with values in $C^\infty(\mathcal{X}\times \mathcal{X})$. In addition, for each set of local coordinates in which $d\mu_{\mathcal{X}}$ coincides with the Lebesgue measure on $\mathbb{R}^n$, there is an open neighborhood $U$ of $0\in\mathbb{R}^n$ such that there exist $\varepsilon>0$, a proper phase function $\psi \in C^\infty(U\times U\times\mathbb{R}^n)$, a symbol $\sigma\in S^1(U,\mathbb{R}^n)$, a function $k\in C^\infty(U\times U\times]-\varepsilon,\varepsilon[)$ and a symbol $q\in S^0(U\times ]-\varepsilon,\varepsilon[\times U,\mathbb{R}^n)$, for which
\[\mathcal{F}_L[\tilde{E}_L'(x,y)](t)=\frac{1}{(2\pi)^n}\int_{\mathbb{R}^n}q(x,t,y,\xi)e^{i(\psi(x,y,\xi)-t\sigma(y,\xi))}d\xi + k(x,y,t).\]
Here $\mathcal{F}_L$ (resp. $'$) denotes the Fourier transform (resp. the derivative) with respect to the variable $L$, in the sense of temperate distributions, and the integral is to be understood in the sense of Fourier integral operators (see Theorem 2.4 of \cite{ho68}). We have
\begin{enumerate}
\item The function $\psi$ satisfies the Equation
\[\forall x,y\in U,\ \xi\in \mathbb{R}^n,\ \sigma(x,\partial_x\psi(x,y,\xi))=\sigma(y,\xi).\]
\item For each $t\in]-\varepsilon,\varepsilon[$ and $\xi\in\mathbb{R}^n$, the function $q(\cdot,t,\cdot,\xi)$ has compact support in $U\times U$ uniformly in $(t,\xi)$ and $q(x,0,y,\xi)-1$ is a symbol of order $-1$ as long as $x,y$ belong to some open neighborhood $U_0$ of $0$ in $U$.
\item $\sigma-\sigma_A^{\frac{1}{m}}\in S^0$.
\end{enumerate}

